STORAGE_NAME = 'Gudang GA'
# Barang yang ikut orangnya; kategori lain diserahkan atas nama departemen
PERSONAL_CATEGORIES = ['Laptop', 'Desktop / PC', 'Kursi Kerja', 'Meja Kerja',
                       'Kasur', 'Tempat Tidur', 'Lemari Pakaian', 'Locker']


def isi_bawaan(apps, schema_editor):
    """Satu tempat titip GA per site + tandai kategori yang bisa diserahkan pribadi."""
    Location = apps.get_model('bibasset', 'Location')
    AssetCategory = apps.get_model('bibasset', 'AssetCategory')
    for site in Location.objects.filter(parent__isnull=True):
        loc, _ = Location.objects.get_or_create(
            name=STORAGE_NAME, parent=site,
            defaults={'full_path': f'{site.full_path or site.name} > {STORAGE_NAME}'},
        )
        if not loc.is_storage:
            loc.is_storage = True
            loc.save(update_fields=['is_storage'])
    AssetCategory.objects.filter(name__in=PERSONAL_CATEGORIES).update(personal_use=True)


def hapus_bawaan(apps, schema_editor):
    Location = apps.get_model('bibasset', 'Location')
    Location.objects.filter(name=STORAGE_NAME, is_storage=True, asset__isnull=True,
                            asset_movements__isnull=True).delete()


